<?php require_once __DIR__.'/../includes/requireLogin.php';require_once __DIR__.'/../includes/authorization.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../repositories/userPDO.php';requireLogin();requireRole('admin');$q=trim((string)($_GET['q']??''));$role=(string)($_GET['role']??'');$status=(string)($_GET['status']??'');if(!in_array($role,['','student','tutor','admin'],true)||!in_array($status,['','active','inactive'],true)){http_response_code(400);exit('Invalid filter');}$rows=searchUsers(openDatabase(),$q,$role,$status);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Manage users</h1><?php if(isset($_GET['updated'])):?><div class="alert alert-success">User updated.</div><?php endif;?><form class="row g-2 mb-3" method="get"><div class="col-md-4"><input class="form-control" name="q" value="<?=htmlspecialchars($q,ENT_QUOTES,'UTF-8')?>" placeholder="Search name or email"></div><div class="col"><select class="form-select" name="role"><option value="">All roles</option><?php foreach(['student','tutor','admin'] as $x):?><option <?=$x===$role?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col"><select class="form-select" name="status"><option value="">All statuses</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactive</option></select></div><div class="col-auto"><button class="btn btn-primary">Search</button></div></form><?php if(!$rows):?><p>No matching accounts.</p><?php else:?><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=htmlspecialchars($u['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($u['email'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($u['roles'],ENT_QUOTES,'UTF-8')?></td><td><?=$u['active']?'Active':'Inactive'?></td><td><a href="manage-user.php?user_id=<?=(int)$u['user_id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></main><?php require __DIR__.'/../includes/footer.php';?>
